/// Error codes reported by ONNX Runtime.
enum OrtErrorCode {
  /// Success. No error occurred.
  ORT_OK(0),

  /// Generic failure that does not map to a more specific error code. Consult
  /// the error message for details.
  ORT_FAIL(1),

  /// A caller-supplied argument was invalid (e.g. NULL pointer, out-of-range
  /// value, mismatched shape/rank, or bad configuration).
  ORT_INVALID_ARGUMENT(2),

  /// A required file (such as a model file) does not exist.
  ORT_NO_SUCHFILE(3),

  /// Legacy/unused but retained for ABI compatibility. Historically returned
  /// when a model could not be found by name in the ONNX Runtime Server
  /// (removed in 2022).
  ORT_NO_MODEL(4),

  /// A hardware accelerator or backend engine reported a failure (e.g. a device
  /// crash or other device-level error).
  ORT_ENGINE_ERROR(5),

  /// A generic runtime exception was caught. The error message is the primary
  /// source of detail.
  ORT_RUNTIME_EXCEPTION(6),

  /// Protobuf parsing or serialization failed.
  ORT_INVALID_PROTOBUF(7),

  /// Invalid session state for the requested operation. Despite the name, this
  /// code does not mean "success, model loaded"; it is returned when the
  /// session is in the wrong state for the requested call (e.g. a model is
  /// already loaded, the session is already initialized, or no model has been
  /// loaded yet). The name is historical and is retained for ABI compatibility;
  /// consult the error message for the specific condition.
  ORT_MODEL_LOADED(8),

  /// The requested functionality is not implemented in this build.
  ORT_NOT_IMPLEMENTED(9),

  /// The model graph is structurally invalid (e.g. recursive function
  /// definitions, invalid tensor dimensions, or malformed nodes).
  ORT_INVALID_GRAPH(10),

  /// An execution provider reported a generic failure.
  ORT_EP_FAIL(11),

  /// Model loading or session initialization was canceled at the caller's
  /// request.
  ORT_MODEL_LOAD_CANCELED(12),

  /// The model requires compilation by an execution provider, but compilation
  /// was disabled via session options.
  ORT_MODEL_REQUIRES_COMPILATION(13),

  /// A requested resource could not be found.
  ORT_NOT_FOUND(14),

  /// The execution provider's hardware device has been reset.
  ORT_DEVICE_RESET(15);

