      };
}

/// Memory types for allocated memory, execution provider specific types should
/// be extended in each provider.
enum OrtMemType {
  /// Any CPU memory used by non-CPU execution provider
  OrtMemTypeCPUInput(-2),

  /// CPU accessible memory outputted by non-CPU execution provider, i.e.
  /// HOST_ACCESSIBLE
  OrtMemTypeCPUOutput(-1),

  /// The default allocator for execution provider
  OrtMemTypeDefault(0);

  /// CPU accessible memory allocated by non-CPU execution provider, i.e.
  /// HOST_ACCESSIBLE
  static const OrtMemTypeCPU = OrtMemTypeCPUOutput;

  final int value;
  const OrtMemType(this.value);

  static OrtMemType fromValue(int value) => switch (value) {
        -2 => OrtMemTypeCPUInput,
        -1 => OrtMemTypeCPUOutput,
        0 => OrtMemTypeDefault,
        _ => throw ArgumentError('Unknown value for OrtMemType: $value'),
      };

  @override
  String toString() {
    if (this == OrtMemTypeCPUOutput)
      return "OrtMemType.OrtMemTypeCPUOutput, OrtMemType.OrtMemTypeCPU";
    return super.toString();
  }
}

/// Algorithm to use for cuDNN Convolution Op
enum OrtCudnnConvAlgoSearch {
  /// expensive exhaustive benchmarking using
  /// cudnnFindConvolutionForwardAlgorithmEx
  OrtCudnnConvAlgoSearchExhaustive(0),

  /// lightweight heuristic based search using
  /// cudnnGetConvolutionForwardAlgorithm_v7
  OrtCudnnConvAlgoSearchHeuristic(1),

  /// default algorithm using CUDNN_CONVOLUTION_FWD_ALGO_IMPLICIT_PRECOMP_GEMM
  OrtCudnnConvAlgoSearchDefault(2);

  final int value;
  const OrtCudnnConvAlgoSearch(this.value);

  static OrtCudnnConvAlgoSearch fromValue(int value) => switch (value) {
        0 => OrtCudnnConvAlgoSearchExhaustive,
        1 => OrtCudnnConvAlgoSearchHeuristic,
        2 => OrtCudnnConvAlgoSearchDefault,
        _ => throw ArgumentError(
            'Unknown value for OrtCudnnConvAlgoSearch: $value'),
      };
}

/// CUDA Provider Options
final class OrtCUDAProviderOptions extends ffi.Struct {
  /// CUDA device Id Defaults to 0.
  @ffi.Int()
  external int device_id;

  /// CUDA Convolution algorithm search configuration. See enum
  /// OrtCudnnConvAlgoSearch for more details. Defaults to
  /// OrtCudnnConvAlgoSearchExhaustive.
  @ffi.UnsignedInt()
  external int cudnn_conv_algo_searchAsInt;

  OrtCudnnConvAlgoSearch get cudnn_conv_algo_search =>
      OrtCudnnConvAlgoSearch.fromValue(cudnn_conv_algo_searchAsInt);

  /// CUDA memory limit (To use all possible memory pass in maximum size_t)
  /// Defaults to SIZE_MAX.
  @ffi.Size()
  external int gpu_mem_limit;

  /// Strategy used to grow the memory arena 0 = kNextPowerOfTwo 1 =
  /// kSameAsRequested Defaults to 0.
  @ffi.Int()
  external int arena_extend_strategy;

  /// Flag indicating if copying needs to take place on the same stream as the
  /// compute stream in the CUDA EP 0 = Use separate streams for copying and
  /// compute. 1 = Use the same stream for copying and compute. Defaults to 1.
  /// WARNING: Setting this to 0 may result in data races for some models.
  /// Please see issue #4829 for more details.
  @ffi.Int()
  external int do_copy_in_default_stream;

  /// Flag indicating if there is a user provided compute stream Defaults to 0.
  @ffi.Int()
  external int has_user_compute_stream;

  /// User provided compute stream. If provided, please set
  /// `has_user_compute_stream` to 1.
  external ffi.Pointer<ffi.Void> user_compute_stream;

  /// CUDA memory arena configuration parameters
  external ffi.Pointer<OrtArenaCfg> default_memory_arena_cfg;

  /// Enable TunableOp for using. Set it to 1/0 to enable/disable TunableOp.
  /// Otherwise, it is disabled by default. This option can be overridden by
  /// environment variable ORT_CUDA_TUNABLE_OP_ENABLE.
  @ffi.Int()
  external int tunable_op_enable;

  /// Enable TunableOp for tuning. Set it to 1/0 to enable/disable TunableOp
  /// tuning. Otherwise, it is disabled by default. This option can be
  /// overridden by environment variable ORT_CUDA_TUNABLE_OP_TUNING_ENABLE.
  @ffi.Int()
  external int tunable_op_tuning_enable;

  /// Max tuning duration time limit for each instance of TunableOp. Defaults to
  /// 0 to disable the limit.
  @ffi.Int()
  external int tunable_op_max_tuning_duration_ms;
}

