/// The OrtEp struct provides functions to implement for an execution provider.
final class OrtEp extends ffi.Struct {
  /// The ONNX Runtime API version the execution provider was compiled with.
  @ffi.Uint32()
  external int ort_version_supported;

  /// Get the execution provider name.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Pointer<ffi.Char> Function(ffi.Pointer<OrtEp> this_ptr)>> GetName;

  /// Get information about the nodes supported by the OrtEp instance.
