                  ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<OrtGraph> graph,
                  ffi.Pointer<OrtEpGraphSupportInfo> graph_support_info)>>
      GetCapability;

  /// Compile OrtGraph instances assigned to the OrtEp. Implementer must set a
  /// OrtNodeComputeInfo instance for each OrtGraph in order to define its
  /// computation function.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<ffi.Pointer<OrtGraph>> graphs,
              ffi.Pointer<ffi.Pointer<OrtNode>> fused_nodes,
              ffi.Size count,
              ffi.Pointer<ffi.Pointer<OrtNodeComputeInfo>> node_compute_infos,
              ffi.Pointer<ffi.Pointer<OrtNode>> ep_context_nodes)>> Compile;

  /// Release OrtNodeComputeInfo instances.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(
              ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<ffi.Pointer<OrtNodeComputeInfo>> node_compute_infos,
              ffi.Size num_node_compute_infos)>> ReleaseNodeComputeInfos;

  /// Get the EP's preferred data layout.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<ffi.UnsignedInt> preferred_data_layout)>>
      GetPreferredDataLayout;

  /// Given an op with domain `domain` and type `op_type`, determine whether an
  /// associated node's data layout should be converted to `target_data_layout`.
  /// If the EP prefers a non-default data layout (see
  /// `GetPreferredDataLayout()`), this function will be called during layout
  /// transformation with `target_data_layout` set to the EP's preferred data
  /// layout.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<ffi.Char> domain,
                  ffi.Pointer<ffi.Char> op_type,
                  ffi.UnsignedInt target_data_layout,
                  ffi.Pointer<ffi.Int> should_convert)>>
      ShouldConvertDataLayoutForOp;

  /// Set dynamic options on this EP.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<ffi.Pointer<ffi.Char>> option_keys,
              ffi.Pointer<ffi.Pointer<ffi.Char>> option_values,
              ffi.Size num_options)>> SetDynamicOptions;

  /// Called by ORT to notify the EP of the start of a run.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<OrtRunOptions> run_options)>> OnRunStart;

  /// Called by ORT to notify the EP of the end of a run.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<OrtRunOptions> run_options,
              ffi.Bool sync_stream)>> OnRunEnd;

  /// Create an OrtAllocator for the given OrtMemoryInfo for an OrtSession.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<OrtMemoryInfo> memory_info,
                  ffi.Pointer<ffi.Pointer<OrtAllocator>> allocator)>>
      CreateAllocator;

  /// Create a synchronization stream for the given memory device for an
  /// OrtSession.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<OrtMemoryDevice> memory_device,
                  ffi.Pointer<ffi.Pointer<OrtSyncStreamImpl>> stream)>>
      CreateSyncStreamForDevice;

  /// Get a string with details about the EP stack used to produce a compiled
  /// model.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Pointer<ffi.Char> Function(
                  ffi.Pointer<OrtEp> this_ptr, ffi.Pointer<OrtGraph> graph)>>
      GetCompiledModelCompatibilityInfo;

  /// Gets the execution provider's kernel registry, if any.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<ffi.Pointer<OrtKernelRegistry>> kernel_registry)>>
      GetKernelRegistry;

  /// Gets whether the execution provider supports concurrent run calls made on
  /// the session.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<ffi.Bool> is_supported)>> IsConcurrentRunSupported;

  /// Called by ORT to block until the device has completed all preceding
  /// requested tasks.
  external ffi.Pointer<
      ffi
      .NativeFunction<OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr)>> Sync;

  /// Return a new profiler for the execution provider.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<ffi.Pointer<OrtEpProfilerImpl>> profiler)>>
      CreateProfiler;

  /// Indicate whether the graph capturing mode (e.g., CUDA graph) is enabled
  /// for the provider.
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Bool Function(ffi.Pointer<OrtEp> this_ptr)>>
      IsGraphCaptureEnabled;

  /// Indicate whether a graph has been captured and instantiated.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Bool Function(
                  ffi.Pointer<OrtEp> this_ptr, ffi.Int graph_annotation_id)>>
      IsGraphCaptured;

  /// Run the instantiated (captured) graph.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtEp> this_ptr, ffi.Int graph_annotation_id)>>
      ReplayGraph;

  /// Get the node assignment validation policy for graph capture.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.UnsignedInt Function(ffi.Pointer<OrtEp> this_ptr)>>
      GetGraphCaptureNodeAssignmentPolicy;

  /// Query the available device resource for partitioning budget.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<OrtResourceCount> available)>> GetAvailableResource;

  /// Called by ORT when session initialization is complete.
  external ffi.Pointer<
          ffi
          .NativeFunction<OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr)>>
      OnSessionInitializationEnd;

  /// Get the EP's default memory device.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
                  ffi.Pointer<ffi.Pointer<OrtMemoryDevice>> device)>>
      GetDefaultMemoryDevice;

  /// Release a previously captured graph and its associated resources.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtEp> this_ptr, ffi.Int graph_annotation_id)>>
      ReleaseCapturedGraph;

  /// Query the execution provider's weightless mode support.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtEp> this_ptr,
              ffi.Pointer<ffi.UnsignedInt> support)>> GetWeightlessSupport;
}

