/// The OrtNodeFusionOptions struct specifies options for fusing nodes supported
/// by an execution provider.
final class OrtNodeFusionOptions extends ffi.Struct {
  /// The ONNX Runtime version the OrtNodeFusionOptions was compiled with.
  @ffi.Uint32()
  external int ort_version_supported;

  /// If set to true, specify that the execution provider does not require ONNX
  /// Runtime to provide constant initializers as inputs to the fused node
  /// during model inference. This is used when the execution provider saves a
  /// copy of constant initializers, and allows ONNX Runtime to release constant
  /// initializers that are not used by any execution provider.
  @ffi.Bool()
  external bool drop_constant_initializers;
}

/// This matches OrtDevice::MemoryType values
enum OrtDeviceMemoryType {
  /// Device memory
  OrtDeviceMemoryType_DEFAULT(0),

  /// Shared/pinned memory for transferring between CPU and the device
  OrtDeviceMemoryType_HOST_ACCESSIBLE(5);

  final int value;
  const OrtDeviceMemoryType(this.value);

  static OrtDeviceMemoryType fromValue(int value) => switch (value) {
        0 => OrtDeviceMemoryType_DEFAULT,
        5 => OrtDeviceMemoryType_HOST_ACCESSIBLE,
        _ =>
          throw ArgumentError('Unknown value for OrtDeviceMemoryType: $value'),
      };
}

