/// Contains functions that an OrtEp implements to specify the computation for
/// an operator kernel.
final class OrtKernelImpl extends ffi.Struct {
  /// Must be initialized to ORT_API_VERSION
  @ffi.Uint32()
  external int ort_version_supported;

  /// EP must initialize to 0. Used internally by ORT.
  @ffi.Uint32()
  external int flags;

  /// Computation function called to execute the kernel on an EP.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtKernelImpl> this_ptr,
              ffi.Pointer<OrtKernelContext> context)>> Compute;

  /// Called by ORT to release the OrtKernelImpl instance and its resources.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<OrtKernelImpl> this_ptr)>> Release;

  /// Optional function to pre-pack a constant tensor (i.e., a weight) to the
  /// kernel's preferred data layout.
