          OrtStatusPtr Function(ffi.Pointer<OrtProfilingEvent> event,
              ffi.Pointer<ffi.Int64> out)>> ProfilingEvent_GetTimestampUs;

  /// Get the duration of a profiling event in microseconds.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<OrtProfilingEvent> event,
              ffi.Pointer<ffi.Int64> out)>> ProfilingEvent_GetDurationUs;

  /// Get the value of an event argument by its key.
