                  ffi.Pointer<OrtProfilingEvent> event,
                  ffi.Pointer<ffi.Char> key,
                  ffi.Pointer<ffi.Pointer<ffi.Char>> out)>>
      ProfilingEvent_GetArgValue;

  /// Add EP profiling events to an events container.
