  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Void Function(
                  ffi.Pointer<OrtExternalResourceImporter> input)>>
      ReleaseExternalResourceImporter;

  /// Check if the external resource importer can import a specific memory
  /// handle type.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.UnsignedInt handle_type,
