  /// Import external memory into the execution provider.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.Pointer<OrtExternalMemoryDescriptor> desc,
              ffi.Pointer<ffi.Pointer<OrtExternalMemoryHandle>>
                  out_handle)>> ImportMemory;

  /// Release an OrtExternalMemoryHandle instance.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Void Function(ffi.Pointer<OrtExternalMemoryHandle> input)>>
      ReleaseExternalMemoryHandle;

  /// Create a tensor backed by imported external memory.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtExternalResourceImporter> importer,
                  ffi.Pointer<OrtExternalMemoryHandle> mem_handle,
                  ffi.Pointer<OrtExternalTensorDescriptor> tensor_desc,
                  ffi.Pointer<ffi.Pointer<OrtValue>> out_tensor)>>
      CreateTensorFromMemory;

  /// Check if the external resource importer can import a specific semaphore
  /// type.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.UnsignedInt type,
              ffi.Pointer<ffi.Bool> out_supported)>> CanImportSemaphore;

  /// Import an external semaphore into the execution provider.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.Pointer<OrtExternalSemaphoreDescriptor> desc,
              ffi.Pointer<ffi.Pointer<OrtExternalSemaphoreHandle>>
                  out_handle)>> ImportSemaphore;

  /// Release an OrtExternalSemaphoreHandle instance.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Void Function(ffi.Pointer<OrtExternalSemaphoreHandle> input)>>
      ReleaseExternalSemaphoreHandle;

  /// Wait on an external semaphore on the EP's stream.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.Pointer<OrtExternalSemaphoreHandle> semaphore_handle,
              ffi.Pointer<OrtSyncStream> stream,
              ffi.Uint64 value)>> WaitSemaphore;

  /// Signal an external semaphore from the EP's stream.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtExternalResourceImporter> importer,
              ffi.Pointer<OrtExternalSemaphoreHandle> semaphore_handle,
              ffi.Pointer<OrtSyncStream> stream,
              ffi.Uint64 value)>> SignalSemaphore;

  /// Initialize graphics interop for an execution provider device.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEpDevice> ep_device,
                  ffi.Pointer<OrtGraphicsInteropConfig> config)>>
      InitGraphicsInteropForEpDevice;

  /// Deinitialize graphics interop for an execution provider device.
  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(ffi.Pointer<OrtEpDevice> ep_device)>>
      DeinitGraphicsInteropForEpDevice;
}

/// Configuration options for creating an OrtEnv.
final class OrtEnvCreationOptions extends ffi.Struct {
  /// Must be set to ORT_API_VERSION
  @ffi.Uint32()
  external int version;

  /// The logging severity level for the environment. Must be set to a value
  /// from OrtLoggingLevel.
  @ffi.Int32()
  external int logging_severity_level;

  /// The log identifier. Must be set to a valid UTF-8 null-terminated string.
  external ffi.Pointer<ffi.Char> log_id;

  /// Optional custom logging function. May be set to NULL.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(
              ffi.Pointer<ffi.Void> param,
              ffi.UnsignedInt severity,
              ffi.Pointer<ffi.Char> category,
              ffi.Pointer<ffi.Char> logid,
              ffi.Pointer<ffi.Char> code_location,
              ffi.Pointer<ffi.Char> message)>> custom_logging_function;

  /// Optional state to pass as the first argument to
  /// OrtEnvCreationOptions::custom_logger_function. May be set to NULL.
  external ffi.Pointer<ffi.Void> custom_logging_param;

  /// Optional threading options for creating an environment with global thread
  /// pools shared across sessions. May be set to NULL.
  external ffi.Pointer<OrtThreadingOptions> threading_options;

  /// Optional environment configuration entries represented as string key-value
  /// pairs. May be set to NULL.
  external ffi.Pointer<OrtKeyValuePairs> config_entries;
}

/// Configuration for thread pool work callbacks.
final class OrtThreadPoolCallbacksConfig extends ffi.Struct {
  /// Must be ORT_API_VERSION
  @ffi.Uint32()
  external int version;

  /// Called when work is enqueued. May be NULL.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Pointer<ffi.Void> Function(
              ffi.Pointer<ffi.Void> user_context)>> on_enqueue;

  /// Called when work starts. May be NULL.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Void> user_context,
              ffi.Pointer<ffi.Void> enqueue_data)>> on_start_work;

  /// Called when work completes. May be NULL.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Void> user_context,
              ffi.Pointer<ffi.Void> enqueue_data)>> on_stop_work;

  /// Called when work is abandoned. May be NULL.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Void> user_context,
              ffi.Pointer<ffi.Void> enqueue_data)>> on_abandon;

  /// User-provided context passed to all callbacks. May be NULL. Must remain
  /// valid for the lifetime of the session. Subject to concurrent invocations
  /// from multiple threads and must be thread-safe. May affect inference
  /// performance.
  external ffi.Pointer<ffi.Void> user_context;
}

/// The C API
final class OrtApi extends ffi.Struct {
  /// Create an OrtStatus from a null terminated string
