/// Specifies some characteristics of inputs/outputs of custom ops: Specify if
/// the inputs/outputs are one of: 1) Non-optional (input/output must be present
/// in the node) 2) Optional (input/output may be absent in the node) 3)
/// Variadic: A variadic input or output specifies N (i.e., the minimum arity)
/// or more operands. Only the last input or output of a custom op may be marked
/// as variadic. The homogeneity of the variadic input or output determines
/// whether all operands must be of the same tensor element type.
enum OrtCustomOpInputOutputCharacteristic {
  INPUT_OUTPUT_REQUIRED(0),
  INPUT_OUTPUT_OPTIONAL(1),
  INPUT_OUTPUT_VARIADIC(2);

  final int value;
  const OrtCustomOpInputOutputCharacteristic(this.value);

  static OrtCustomOpInputOutputCharacteristic fromValue(int value) =>
      switch (value) {
        0 => INPUT_OUTPUT_REQUIRED,
        1 => INPUT_OUTPUT_OPTIONAL,
        2 => INPUT_OUTPUT_VARIADIC,
        _ => throw ArgumentError(
            'Unknown value for OrtCustomOpInputOutputCharacteristic: $value'),
      };
}

/// The OrtCustomOp structure defines a custom op's schema and its kernel
/// callbacks. The callbacks are filled in by the implementor of the custom op.
final class OrtCustomOp extends ffi.Struct {
  /// Initialize to ORT_API_VERSION. ORT will cap the API version used to select
  /// the OrtApi passed to CreateKernel/CreateKernelV2 callbacks, so custom ops
  /// compiled against a newer ORT can load on an older runtime if they only use
  /// APIs available at the runtime version. Newer OrtCustomOp function pointers
  /// are gated by per-function version checks within ORT.
  @ffi.Uint32()
  external int version;

  /// This callback creates the kernel, which is a user defined parameter that
  /// is passed to the Kernel* callbacks below. It is recommended to use
  /// CreateKernelV2 which allows for a safe error propagation by returning an
  /// OrtStatusPtr.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Pointer<ffi.Void> Function(
              ffi.Pointer<OrtCustomOp> op,
              ffi.Pointer<OrtApi> api,
              ffi.Pointer<OrtKernelInfo> info)>> CreateKernel;

  /// Returns the name of the op
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Pointer<ffi.Char> Function(ffi.Pointer<OrtCustomOp> op)>> GetName;

  /// Returns the type of the execution provider, return nullptr to use CPU
  /// execution provider
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Pointer<ffi.Char> Function(ffi.Pointer<OrtCustomOp> op)>>
      GetExecutionProviderType;

  /// Returns the count and types of the input & output tensors
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.UnsignedInt Function(
              ffi.Pointer<OrtCustomOp> op, ffi.Size index)>> GetInputType;

  external ffi.Pointer<
          ffi.NativeFunction<ffi.Size Function(ffi.Pointer<OrtCustomOp> op)>>
      GetInputTypeCount;

  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.UnsignedInt Function(
              ffi.Pointer<OrtCustomOp> op, ffi.Size index)>> GetOutputType;

  external ffi.Pointer<
          ffi.NativeFunction<ffi.Size Function(ffi.Pointer<OrtCustomOp> op)>>
      GetOutputTypeCount;

  /// Perform a computation step. It is recommended to use KernelComputeV2 which
  /// allows for a safe error propagation by returning an OrtStatusPtr.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Void> op_kernel,
              ffi.Pointer<OrtKernelContext> context)>> KernelCompute;

  external ffi.Pointer<
          ffi
          .NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void> op_kernel)>>
      KernelDestroy;

  /// Returns the characteristics of the input & output tensors
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.UnsignedInt Function(
                  ffi.Pointer<OrtCustomOp> op, ffi.Size index)>>
      GetInputCharacteristic;

  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.UnsignedInt Function(
                  ffi.Pointer<OrtCustomOp> op, ffi.Size index)>>
      GetOutputCharacteristic;

  /// Returns the memory type of the input tensors. This API allows the custom
  /// op to place the inputs on specific devices. By default, it returns
  /// OrtMemTypeDefault, which means the input is placed on the default device
  /// for the execution provider. If the inputs need to be with different memory
  /// types, this function can be overridden to return the specific memory
  /// types.
  external ffi.Pointer<
          ffi.NativeFunction<
              ffi.Int Function(ffi.Pointer<OrtCustomOp> op, ffi.Size index)>>
      GetInputMemoryType;

  /// Returns the minimum number of input arguments expected for the variadic
  /// input. Applicable only for custom ops that have a variadic input.
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetVariadicInputMinArity;

  /// Returns true (non-zero) if all arguments of a variadic input have to be of
  /// the same type (homogeneous), and false (zero) otherwise. Applicable only
  /// for custom ops that have a variadic input.
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetVariadicInputHomogeneity;

  /// Returns the minimum number of output values expected for the variadic
  /// output. Applicable only for custom ops that have a variadic output.
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetVariadicOutputMinArity;

  /// Returns true (non-zero) if all outputs values of a variadic output have to
  /// be of the same type (homogeneous), and false (zero) otherwise. Applicable
  /// only for custom ops that have a variadic output.
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetVariadicOutputHomogeneity;

  /// Create the kernel state which is passed to each compute call.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(
              ffi.Pointer<OrtCustomOp> op,
              ffi.Pointer<OrtApi> api,
              ffi.Pointer<OrtKernelInfo> info,
              ffi.Pointer<ffi.Pointer<ffi.Void>> kernel)>> CreateKernelV2;

  /// Perform the computation step.
  external ffi.Pointer<
      ffi.NativeFunction<
          OrtStatusPtr Function(ffi.Pointer<ffi.Void> op_kernel,
              ffi.Pointer<OrtKernelContext> context)>> KernelComputeV2;

  external ffi.Pointer<
          ffi.NativeFunction<
              OrtStatusPtr Function(
                  ffi.Pointer<OrtCustomOp>, ffi.Pointer<OrtShapeInferContext>)>>
      InferOutputShapeFn;

  /// Get start range
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetStartVersion;

  external ffi.Pointer<
          ffi.NativeFunction<ffi.Int Function(ffi.Pointer<OrtCustomOp> op)>>
      GetEndVersion;

  /// Get the inplace_map that defines which output can reuse which input
  /// Callers will provide 2 raw int* and pass in their address, this function
  /// will fill these 2 arrays when return, output (*output_index)[i] may reuse
  /// the input (*input_index[i]). The return value is the size of these 2
  /// arrays. Callers are responsible to delete these 2 arrays after use by
  /// calling OrtCustomOp::ReleaseMayInplace().
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Size Function(ffi.Pointer<ffi.Pointer<ffi.Int>> input_index,
              ffi.Pointer<ffi.Pointer<ffi.Int>> output_index)>> GetMayInplace;

  /// Release the pointer input_index and output_index allocated from
  /// GetMayInplace() function. If GetMayInplace() is defined, this function
  /// MUST be defined as well.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Int> input_index,
              ffi.Pointer<ffi.Int> output_index)>> ReleaseMayInplace;

  /// Same as GetMayInplace() and ReleaseMayInplace()
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Size Function(ffi.Pointer<ffi.Pointer<ffi.Int>> input_index,
              ffi.Pointer<ffi.Pointer<ffi.Int>> output_index)>> GetAliasMap;

  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<ffi.Int> input_index,
              ffi.Pointer<ffi.Int> output_index)>> ReleaseAliasMap;
}

/// The helper interface to get the right version of OrtApi
final class OrtApiBase extends ffi.Struct {
  /// Get a pointer to the requested version of the ::OrtApi
  external ffi.Pointer<
          ffi.NativeFunction<ffi.Pointer<OrtApi> Function(ffi.Uint32 version)>>
      GetApi;

  /// Returns a null terminated string of the version of the Onnxruntime library
  /// (eg: "1.8.1")
  external ffi.Pointer<ffi.NativeFunction<ffi.Pointer<ffi.Char> Function()>>
      GetVersionString;
}

const int ORT_API_VERSION = 29;
